// This display plan belongs to the saved opening View. It changes the objects
// carrying the work without changing the document, its sources or its route.
export const flagshipExhibitionCuration = Object.freeze({
  question: 'What can Henry’s memories tell us about him?',
  sections: Object.freeze([
    {
      heading: 'A life across places',
      works: [
        ['about:root:about-me', 'photographs'],
        ['interactive.travels.globe', 'globe'],
      ],
    },
    {
      heading: 'The familiarity of home',
      works: [
        // A personal journal, a table memory, then an open vertical page.
        ['fragments:napier-seaside-with-my-mother', 'folio'],
        ['fragments:mothers-cooking-across-places', 'reading-case'],
        ['fragments:kennedy-town-seaside-hku-years', 'hanging-scroll'],
      ],
    },
    {
      heading: 'Travelling together',
      works: [
        // The road advances continuously. The family visit has a journal stand.
        ['fragments:great-ocean-road-melbourne-friends', 'reading-roll'],
        ['fragments:athens-ruins-and-family-trip', 'folio'],
      ],
    },
    {
      heading: 'Remembering a changing life',
      works: [
        // Photographs use the original boards. The final essay can keep advancing.
        ['about:gallery', 'photographs'],
        ['fragments:identity-interview-reflection', 'hanging-scroll'],
        ['fragments:memory-time-self', 'reading-roll'],
      ],
    },
  ].map(section => Object.freeze({
    ...section,
    works: Object.freeze(section.works.map(([sourceId, form]) => Object.freeze({ sourceId, form }))),
  }))),
});

// Source order and chapter identity protect other Views that happen to ask
// the same question. Narrative edits and inserted bridges do not move a work
// onto another carrier. Each chapter owns its own source-to-form assignment.
export function curatedExhibitionForms(view) {
  const plan = flagshipExhibitionCuration;
  if (view?.question !== plan.question || view.sections?.length !== plan.sections.length) return {};
  const mapping = {};
  for (const [sectionIndex, section] of view.sections.entries()) {
    const chapter = plan.sections[sectionIndex];
    if (section.heading !== chapter.heading) return {};
    const works = (section.blocks || []).flatMap((block, blockIndex) => block.kind === 'source' ? [{ block, blockIndex }] : []);
    if (works.length !== chapter.works.length) return {};
    for (const [workIndex, { block, blockIndex }] of works.entries()) {
      const assignment = chapter.works[workIndex];
      if (block.source_id !== assignment.sourceId) return {};
      mapping[`${sectionIndex}-${blockIndex}`] = assignment.form;
    }
  }
  return mapping;
}
